SELECT Version,count() AS Installations FROM (SELECT toString(properties.installation_id) AS Installation,argMax(toString(properties.app_version),timestamp) AS Version FROM events WHERE event IN ('native_app_opened','native_app_active') AND (properties.environment = 'production' AND properties.product = 'studio') AND properties.installation_id IS NOT NULL AND {filters} GROUP BY Installation) GROUP BY Version ORDER BY Installations DESC LIMIT 30
